mapper.delete:
DELETE FROM diag_result_trends
WHERE tenant_id = #{tenantId}
  AND query_hash = #{queryHash}
  AND data_version = #{dataVersion}

mapper.select:
WITH latest_version AS ( SELECT TOP 1 data_version FROM diag_result_publish_version WHERE tenant_id = #{tenantId} AND query_hash = #{queryHash} AND publish_status = 'PUBLISHED' ORDER BY published_time DESC, update_time DESC, id DESC ) SELECT id, tenant_id AS tenantId, query_hash AS queryHash, metric_code AS metricCode, point_date AS pointDate, current_value AS currentValue, compare_value AS compareValue, growth_rate AS growthRate, period_label AS periodLabel, data_version AS dataVersion, snapshot_time AS snapshotTime, create_time AS createTime, update_time AS updateTime FROM diag_result_trends WHERE tenant_id = #{tenantId} AND query_hash = #{queryHash} AND data_version = (SELECT data_version FROM latest_version)
AND metric_code = #{metricCode}
ORDER BY point_date ASC, id ASC

SELECT id, tenant_id AS tenantId, query_hash AS queryHash, metric_code AS metricCode, point_date AS pointDate, current_value AS currentValue, compare_value AS compareValue, growth_rate AS growthRate, period_label AS periodLabel, data_version AS dataVersion, snapshot_time AS snapshotTime, create_time AS createTime, update_time AS updateTime FROM diag_result_trends WHERE tenant_id = #{tenantId} AND query_hash = #{queryHash} AND data_version = #{dataVersion}
AND metric_code = #{metricCode}
ORDER BY point_date ASC, id ASC
